local PRIORITY={underbarrel=30,launcher=30,vertical=20,angled=10,horizontal=10}
function G.isCustom(id)
    return id~=nil and id~='vanilla' and id~='Handgun' and id~='TW_Rifle' and id~='Rifle'
end
local function supportPriority(variant)
    if variant.priority then return variant.priority end
    local kind=variant.supportClass or ''
    if kind:find('underbarrel') or kind:find('launcher') then return 30 end
    return PRIORITY[kind] or 10
end

local function ancestorsMatch(tree,variant)
    for path,tpl in pairs(variant.ancestors or {}) do
        if tree[path]~=tpl then return false end
    end
    return true
end

local function chooseSupport(tree)
    local selected,selectedTpl,selectedKind,rank=nil,nil,nil,-1
    for path,tpl in pairs(tree) do
        local info=G.supports[tpl]
        if info then
            local priority=info.priority or 50
            if priority>rank or priority==rank and (not selected or path<selected) then
                selected,selectedTpl,selectedKind,rank=path,tpl,info.type,priority
            end
        end
    end
    return selected,selectedTpl,selectedKind
end

local function sameTree(a,b)
    local count=0
    for path,tpl in pairs(a) do
        if b[path]~=tpl then return false end
        count=count+1
    end
    local other=0
    for _ in pairs(b) do other=other+1 end
    return count==other
end

local function pairedRecipe(row,key,tree,folded,path,tpl)
    local match=nil
    for _,recipe in ipairs(row.pairedRecipes or {}) do
        if recipe.folded==folded and recipe.rootTpl==C.root(key)
                and recipe.selectedSupportPath==path and recipe.selectedSupportTpl==tpl
                and sameTree(recipe.tree,tree) then
            if match and match~=recipe.classId then return nil,'ambiguous-paired-assembly' end
            match=recipe.classId
        end
    end
    return match,match and 'exact-paired-assembly' or nil
end

local function distance(a,b)
    return math.sqrt((a[1]-b[1])^2+(a[2]-b[2])^2+(a[3]-b[3])^2)
end

local function nearestSupport(key,tree,path,tpl,kind,row)
    local item=C.data.items[tpl]
    local frame=C.placement(key,tree,path)
    local b=item and item.bounds
    if not frame or not b then return nil end
    local centre={(b.min[1]+b.max[1])/2,(b.min[2]+b.max[2])/2,(b.min[3]+b.max[3])/2}
    local contact=C.toRender(key,C.transformPoint(frame,centre))
    local candidates=G.fallbacks[row.baseFamily] and G.fallbacks[row.baseFamily][kind]
    if not candidates or #candidates==0 then
        candidates={}
        for id,class in pairs(G.classes) do if class.supportClass==kind then candidates[#candidates+1]=id end end
        table.sort(candidates)
    end
    local best,error=nil,math.huge
    for _,id in ipairs(candidates) do
        local class=G.classes[id]
        if class and class.leftPosition and class.rightPosition and row.rightPosition then
            -- Unknown assemblies are compared in the original support-contact
            -- space. An anatomical wrist offset must not bias nearest support
            -- selection; these unseen combinations remain approximate.
            local classContact=class.leftContactPosition or class.leftPosition
            local residual=math.max(distance(contact,classContact),distance(row.rightPosition,class.rightPosition))
            if residual<error then best,error=id,residual end
        end
    end
    return best
end

function G.classForAssembly(key,tree,folded,readProblem)
    local row=G.weapons[key]
    if not row then return nil end
    local desired=folded and row.foldedClass or row.baseClass or row.classId
    local path,tpl,kind=chooseSupport(tree)
    if row.pairedRecipes then
        -- These recipes bind BOTH hands, including sibling PG, stock/chassis,
        -- selected support, all empty/extra slots and the authored fold state.
        -- A nearest profile for an unseen tree remains explicitly approximate.
        if readProblem then return nil,'invalid-tree:'..readProblem end
        local valid,reason=C.validate(key,tree)
        if not valid then return nil,'invalid-tree:'..tostring(reason) end
        if #C.requiredMissing(key,tree)>0 then return nil,'incomplete-assembly' end
        local exact,quality=pairedRecipe(row,key,tree,folded,path,tpl)
        if exact or quality then return exact,quality end
        local nearest=path and nearestSupport(key,tree,path,tpl,kind,row)
        return nearest or desired,'approximate-paired-assembly'
    end
    local score=-1
    for _,v in ipairs(row.variants or {}) do
        if (not path or path==v.path) and (v.folded==nil or v.folded==folded)
                and tree[v.path]==v.supportTpl and ancestorsMatch(tree,v) then
            local rank=supportPriority(v)
            if rank>score then desired=v.classId;score=rank end
        end
    end
    if path and score<0 then
        local nearest=nearestSupport(key,tree,path,tpl,kind,row)
        if nearest then return nearest,'approximate' end
    end
    return desired,score>=0 and 'exact-support' or 'base'
end

function G.folded(gun)
    local md=gun:getModData()
    -- Folding is not currently a runtime mechanic. These explicit fields allow
    -- a future authoritative assembly state to choose its authored class.
    return (md.TW and md.TW.folded==true) or md.TWFolded==true
end

-- The grip class the weapon plays (GunworksGripAnim): the reference class of its
-- support (TW/GripTargets, runtime transfer in GripIK.java), its own class (RSHG),
-- or the native 'Handgun' (handguns route by TWCarryHandgunProfile instead).
function G.classFor(gun)
    local key=R.visualKey(gun)
    if not key or not G.weapons[key] then return nil end
    local Targets=targets()
    local base=G.weapons[key].baseClass
    if Targets.isRocket(key) or not G.isCustom(base) then return base end
    local v=Targets.forGun(gun,false)
    return v and v.refClass or nil
end

-- Reference classes per support kind (TW/GripTargets) and the RSHG class. The
-- per-assembly classes of G.weapons/G.classes stay as data: the clips of the old
-- per-class bank are gone, GripIK.java moves the hands at runtime.
function G.register()
    if G.registered then return end
    local Targets=require('TW/GripTargets')
    Targets.register(Grip)
    local n=0
    for key,row in pairs(G.weapons) do
        if Targets.isRocket(key) then
            Grip.RegisterWeapon(row.pz,{id='TW:grip:'..key,animId=row.baseClass})
            n=n+1
        end
    end
    G.registered=true
    print('[TW] Registered grips: '..#Targets.kinds..' reference classes, '..n..' own')
end

-- CODE ONLY: append before `return G` in the owned shared TW/Grips.lua.
-- Independent TW protocol and preference. No Tactical Hold implementation.
-- FB4 (the user's item 2, 19.10.2026): the carry stance of every weapon of the mod is one of
-- low/high/patrol, Patrol by default. The former "no stance" ('idle': the base AnimSet nodes, the
-- vanilla rifle idle in isometric) is gone; a shot or the side mouse button in Viewpoint's first
-- person only raises the weapon to its first-person ready (TW_TacHoldOverride.ready), the stance stays.
G.Carry={module='TWCarryV1',defaultMode='patrol',mdKey='TWCarryV1',version=2,installed=false}
local Carry=G.Carry
local serverActors=setmetatable({},{__mode='k'})
local nextGeneration,revision=0,0
local epoch=tostring(getTimestampMs())
local function integer(value)
 return type(value)=='number' and value==math.floor(value) and value>=0 and value<=2147483647
end
local function itemId(value)
 return type(value)=='number' and value==math.floor(value) and value>=-2147483648 and value<=2147483647
end
function Carry.validMode(mode)return mode=='low' or mode=='high' or mode=='patrol' end
-- Reference classes whose body has patrol clips and nodes (tools/patrol_nodes.py).
local patrolClasses={TW_Contact_P101=true,TW_Contact_P026=true,TW_Contact_P121=true,TW_Contact_P074=true,TW_Contact_P076=true}
-- The body of the weapon in hands plays its own patrol (the AnimSets have it for its class).
function Carry.canPatrol(player)
 local gun=player and player:getPrimaryHandItem()
 -- Deployed launcher proxies may render as a rifle host through visualKey; they keep low/high.
 return gun~=nil and R.key(gun)~=nil and patrolClasses[G.classFor(gun)]==true
end
-- Every stance is offered for every weapon of the mod. A class without body patrol clips (handguns,
-- RSHG-2, a deployed underbarrel) carries Patrol in its Low Ready body pose (Carry.animMode); in
-- Viewpoint's first person it plays Tarkov's own patrol clips of its family where they exist.
function Carry.availableMode(player,mode)
 return Carry.validMode(mode)
end
function Carry.modeFor(player,mode)
 return Carry.validMode(mode) and mode or Carry.defaultMode
end
-- The stance the body's AnimSets play (TWCarryMode).
function Carry.animMode(player,mode)
 if mode=='patrol' and not Carry.canPatrol(player) then return 'low' end
 return mode
end
function Carry.nextMode(player,mode)
 if mode=='low' then return 'high' end
 if mode=='high' then return 'patrol' end
 return 'low'
end
-- The saved stance. Version 1 (up to FB4) stored 'low' also as the old default (and on death or as the
-- server's first answer) and 'idle' after a shot: both read as the new default; an explicit high or
-- patrol stays. From version 2 every stored choice is the player's own.
function Carry.preference(player)
 local md=player:getModData();local stored=md[Carry.mdKey]
 if type(stored)~='table' or not Carry.validMode(stored.mode) then return Carry.defaultMode end
 if (tonumber(stored.version) or 1)<Carry.version and stored.mode=='low' then return Carry.defaultMode end
 return stored.mode
end
function Carry.persist(player,mode)
 assert(Carry.validMode(mode));player:getModData()[Carry.mdKey]={version=Carry.version,mode=mode}
end
-- A stance stored before version 2 is written once in the new form (with a log line).
function Carry.migrate(player)
 local md=player and player:getModData();local stored=md and md[Carry.mdKey]
 if type(stored)~='table' or (tonumber(stored.version) or 1)>=Carry.version then return false end
 local mode=Carry.preference(player)
 print('[TW-CARRY] saved stance v'..tostring(stored.version or 1)..' '..tostring(stored.mode)..' -> '..mode)
 Carry.persist(player,mode)
 return true
end
function Carry.routeReady(player)
 if not player or player:isDead() or player:getVehicle() then return false end
 if not R.visualKey(player:getPrimaryHandItem()) then return false end
 -- An action that animates sets PerformingAction / IsPerformingAnAction (BaseAction.setActionAnim). One
 -- that does not (walking to a container: ISWalkToTimedAction) keeps the stance; a queued action
 -- alone played the vanilla walk before (FB4, the user's item 2).
 if (player:getVariableString('PerformingAction')or'')~='' then return false end
 if player:getVariableBoolean('isLoading')or player:getVariableBoolean('isRacking')or player:getVariableBoolean('isUnloading')then return false end
 -- Walk/run/sprint/crouch/sneak are ordinary carry; never gate on movement.
 return true
end
function Carry.canCarry(player)
 return Carry.routeReady(player) and not player:isAiming()
end
local function serverState(player)
 local state=serverActors[player]
 if not state then
  nextGeneration=nextGeneration+1;revision=revision+1
  state={generation=nextGeneration,revision=revision,mode=Carry.preference(player)}
  serverActors[player]=state
 end
 return state
end
local function payload(player,state)
 return {playerId=player:getOnlineID(),generation=state.generation,revision=state.revision,mode=state.mode,epoch=epoch,
  session=state.session,sequence=state.sequence}
end
local function setServerMode(player,mode)
 local state=serverState(player)
 -- Every admitted request gets an acknowledgement, including a re-selection of the same mode.
 state.mode=mode;revision=revision+1;state.revision=revision
 Carry.persist(player,mode)
 sendServerCommand(Carry.module,'State',payload(player,state))
end
function Carry.installAuthority()
 if Carry.installed or not isServer() then return end
 Carry.installed=true
 Events.OnClientCommand.Add(function(module,command,player,args)
  if module~=Carry.module or not player or type(args)~='table' then return end
  local state=serverState(player);local now=getTimestampMs()
  if command=='Sync'then
   if state.lastSync and now-state.lastSync<2000 then return end
   state.lastSync=now;local rows={};local players=getOnlinePlayers()
   for i=0,players:size()-1 do local actor=players:get(i);rows[#rows+1]=payload(actor,serverState(actor))end
   sendServerCommand(player,Carry.module,'Snapshot',{epoch=epoch,states=rows})
   return
  end
  -- A shot no longer clears the stance (FB4): the former 'Fired' request is refused like any other.
  if command~='SetMode' or not Carry.canCarry(player) or not Carry.availableMode(player,args.mode)
   or not itemId(args.weaponId) or not integer(args.sequence) or args.sequence<1
   or type(args.session)~='string' or #args.session<1 or #args.session>40 then return end
  local weapon=player:getPrimaryHandItem()
  if player:isDead() then return end
  if not weapon or weapon:getID()~=args.weaponId or not R.visualKey(weapon) then return end
  if state.lastRequest and now-state.lastRequest<250 then return end
  if state.session==args.session and state.sequence and args.sequence<=state.sequence then return end
  state.lastRequest=now
  state.session=args.session;state.sequence=args.sequence
  -- Actor identity is the native OnClientCommand owner, never supplied by args.
  setServerMode(player,args.mode)
 end)
 Events.OnTick.Add(function()
  local players=getOnlinePlayers()
  for i=0,players:size()-1 do
   local player=players:get(i);local state=serverState(player)
   if player:isDead() and state.mode~=Carry.defaultMode then setServerMode(player,Carry.defaultMode)end
  end
 end)
end
Carry.installAuthority()

