-- Every own handgun plays the handgun reference profile; GripIK.java moves the hands
-- onto its own grip (TW/GripTargets handguns, by the catalogue class above).
function G.Carry.handgunProfile(weapon)
 local key=R.key(weapon)
 return key and ownHandgunCatalogue[key] and targetsData().handgunClass or nil
end
function G.Carry.refreshHandgunRouting(player)
 if not player then return end
 local owned=not player:isDead() and R.visualKey(player:getPrimaryHandItem())~=nil
 local profile=owned and G.Carry.handgunProfile(player:getPrimaryHandItem()) or nil
 if profile then player:setVariable('TWCarryHandgunProfile',profile)
 else player:clearVariable('TWCarryHandgunProfile') end
 player:setVariable('TWCarryHandgunActive',profile~=nil and G.Carry.canCarry(player))
 player:setVariable('TWCarryHandgunRouteReady',profile~=nil and G.Carry.routeReady(player))
end

-- Append after handgun_carry_routes.lua, before the shared final return G.
-- Held selection persists while aiming/shooting; carry retains its own guards.
local previousHandgunRouting = G.Carry.refreshHandgunRouting
function G.Carry.refreshHandgunRouting(player)
 previousHandgunRouting(player)
 if not player then return end
 local owned = not player:isDead() and R.visualKey(player:getPrimaryHandItem()) ~= nil
 local profile = owned and G.Carry.handgunProfile(player:getPrimaryHandItem()) or nil
 player:setVariable('TWCarryHandgunHeldReady', profile ~= nil)
end

-- CODE ONLY. Append after both handgun routing fragments, before shared return G.
-- Gate actual native gesture contexts, retaining their original primary/weights.
-- This is independent of the stored low/high preference and of foreign weapons.
local previousHandgunRouteReady = G.Carry.routeReady
-- FB4 (the user's items 2 and 8, 19.10.2026): only an action's own animation releases the stance.
-- The idle fidget (IsoPlayer.onIdlePerformFidgets) sets the variable Ext and never clears it: after
-- the first fidget (about 100 s of standing still, at a random moment) Ext stayed set, the stance
-- route stayed off for good - the vanilla pose, the stance key and menu refused - until the save was
-- loaded again. A fidget itself (ExtPlaying) keeps the stance: its own ext nodes play the stance's
-- idle (tools/carry_ext_nodes.py), never the vanilla fidget.
function G.Carry.handgunReleasedContext(player)
    if not player or not G.Carry.handgunProfile(player:getPrimaryHandItem()) then return false end
    return player:getVariableBoolean('IsPerformingAnAction')
end
function G.Carry.routeReady(player)
    return previousHandgunRouteReady(player) and not G.Carry.handgunReleasedContext(player)
end
-- No source-contact phase is manufactured here. The full Source dispatcher must
-- separately exclude unbound gesture curves and preserve literal native action
-- boundary animations; this gate alone does not qualify those curves or seams.

-- CODE ONLY: append after owned Carry and any handgun routing/gate fragments.
-- Scope is the existing owned rifle selector map, including its RSHG class.
local previousRifleRouteReady = G.Carry.routeReady
function G.Carry.rifleReleasedContext(player)
    if not player then return false end
    local item = player:getPrimaryHandItem()
    local key = item and R.visualKey(item)
    if not key or not G.weapons[key] then return false end
    -- As for handguns above: the stale Ext of a past fidget no longer counts.
    return player:getVariableBoolean('IsPerformingAnAction')
end
function G.Carry.routeReady(player)
    return previousRifleRouteReady(player) and not G.Carry.rifleReleasedContext(player)
end
-- Integration must separately select literal native gesture Source and weights.
-- This eligibility gate does not qualify their exit/crossfade or game visuals.

-- FB4 (19.10.2026, the user's item 18: "exits from animations are too jerky"; FB4-A's frames, run5-layers): the stance
-- came back the same frame an action ended, so the root layer cross-faded into the stance (0.20 s) while the action
-- node was still fading out (ActionExits: Tarkov's 0.25 s on every mod action node); PZ orders live tracks by weight,
-- and at the root's half-way point the order flipped - the pose jumped about 40 degrees in one frame (reload, rack,
-- inspect exits). After an action the route now stays off for EXIT_S more, counted from the action's end: a new action
-- restarts it, another weapon or death ends it, and it never lasts longer (no stuck route, item 8).
G.Carry.EXIT_S = 0.25
local exits = setmetatable({}, {__mode = 'k'})
local function acting(player)
    return (player:getVariableString('PerformingAction') or '') ~= '' or player:getVariableBoolean('isLoading')
        or player:getVariableBoolean('isRacking') or player:getVariableBoolean('isUnloading')
        or player:getVariableBoolean('IsPerformingAnAction')
end
-- True while the stance waits for an action's exit cross-fade (the route is off for that alone).
function G.Carry.actionExit(player, now)
    local e = player and exits[player]
    if not e or not e.at then return false end
    if player:isDead() or e.weapon ~= player:getPrimaryHandItem() or (now or getTimestampMs()) - e.at >= G.Carry.EXIT_S * 1000 then
        exits[player] = nil
        return false
    end
    return true
end
local previousExitRouteReady = G.Carry.routeReady
function G.Carry.routeReady(player)
    local ready = previousExitRouteReady(player)
    if not player then return ready end
    if acting(player) then
        exits[player] = {weapon = player:getPrimaryHandItem()}
        return ready
    end
    local e = exits[player]
    if e and not e.at then e.at = getTimestampMs() end
    return ready and not G.Carry.actionExit(player)
end

-- FB5 (the user's item 2, 20.10.2026: "after a reload the weapon spins round its axis"): the mod's own weapon actions
-- (reload, unload, rack, magazine check or drop, the weapon utilities) keep the stance's node on the base layer -
-- TWCarryActionStance, the second condition group of the idle stance nodes (tools/patrol_nodes.py). Their clips are
-- built on the class's reload pose and blend straight from and back to the stance; the class's own idle under them
-- held the right arm a half turn from the stance's, and the rifle on the hand swung the long way round at each entry
-- and exit (~280 degrees, the female P101). An action of another kind still releases the stance. After the action the
-- stance holds until its route is back (the exit, Carry.EXIT_S), at most ACTION_HOLD_S.
G.Carry.ACTION_HOLD_S = 3
-- QA (A/B in one run): false releases the stance for every action, as before FB5.
G.Carry.actionStanceOn = true
local held = setmetatable({}, {__mode = 'k'})
function G.Carry.ownAction(player)
    return player:getVariableBoolean('isLoading') or player:getVariableBoolean('isRacking') or player:getVariableBoolean('isUnloading')
        or player:getVariableBoolean('TWMagCheck') or player:getVariableBoolean('TWMagDrop')
        or (player:getVariableString('TWWeaponUtility') or '') ~= ''
end
-- route: Carry.routeReady of this update.
function G.Carry.actionStance(player, route, now)
    local gun = player and player:getPrimaryHandItem()
    if not gun or not G.Carry.actionStanceOn or player:isDead() or player:getVehicle() or not R.visualKey(gun) then
        if player then held[player] = nil end
        return false
    end
    now = now or getTimestampMs()
    if G.Carry.ownAction(player) then
        held[player] = {weapon = gun, at = now}
        return true
    end
    local h = held[player]
    if not h or h.weapon ~= gun or route or now - h.at >= G.Carry.ACTION_HOLD_S * 1000 then
        held[player] = nil
        return false
    end
    return true
end

-- Why the stance route is off now (nil: it is on): the tests of Carry.routeReady and its gates above,
-- named for the stance key's [TW-CARRY] line (FB4, the user's item 8).
function G.Carry.routeRefusal(player)
    if not player then return 'no player' end
    if player:isDead() then return 'dead' end
    if player:getVehicle() then return 'in a vehicle' end
    if not R.visualKey(player:getPrimaryHandItem()) then return 'no weapon of the mod in hands' end
    local action = player:getVariableString('PerformingAction') or ''
    if action ~= '' then return 'action animation '..action end
    for _, name in ipairs({'isLoading', 'isRacking', 'isUnloading'}) do
        if player:getVariableBoolean(name) then return name..' set' end
    end
    if G.Carry.handgunReleasedContext(player) or G.Carry.rifleReleasedContext(player) then return 'action running (IsPerformingAnAction)' end
    if G.Carry.actionExit(player) then return 'action exit (0.25 s)' end
    if not G.Carry.routeReady(player) then return 'stance route off' end
end

-- Performance pass (23.10.2026): one route decision per player and stance update. TW_TacHoldOverride's update asked it
-- four times (handgun routing, carry, route, action stance), ~20 reflective reads each, for the same player in the same
-- instant; inside Carry.withRoute(player, fn) the first answer is reused. Elsewhere every call decides anew.
local routeMemo
local previousMemoRouteReady = G.Carry.routeReady
-- QA A/B: true decides every call anew, as before.
G.Carry.memoOff = false
function G.Carry.routeReady(player)
    local memo = routeMemo
    if memo and memo.player == player and not G.Carry.memoOff then
        if memo.ready == nil then memo.ready = previousMemoRouteReady(player) end
        return memo.ready
    end
    return previousMemoRouteReady(player)
end
function G.Carry.withRoute(player, fn)
    local outer = routeMemo
    routeMemo = {player = player}
    local ok, err = pcall(fn, player)
    routeMemo = outer
    if not ok then error(err) end
end

return G
